$ErrorActionPreference="Stop";$root=Split-Path -Parent $PSScriptRoot;$file=Join-Path $root ".local\processes.json";if(Test-Path $file){$s=Get-Content $file -Raw|ConvertFrom-Json;foreach($id in @($s.backend,$s.frontend)){if($id){Stop-Process -Id $id -Force -ErrorAction SilentlyContinue}};Remove-Item $file;Write-Host "Stopped CI-Sense services."}else{Write-Host "No CI-Sense process IDs found."}